package com.greenocean.backend.professional.service;

import com.greenocean.backend.auth.service.RecentAuthentication;
import com.greenocean.backend.common.exception.*;
import com.greenocean.backend.catalog.service.GrowthLibrary;
import com.greenocean.backend.identity.AccessPolicy;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import java.time.*;
import java.util.*;
import static com.greenocean.backend.professional.service.ProfessionalAuthority.time;

/** Purpose-separated operations. Operational projections never join clinical narrative tables. */
@Service @Transactional
public class ClinicIntegration {
 private final JdbcTemplate db;private final ClinicalCare care;private final ClinicCommerce commerce;private final ProfessionalAuthority authority;private final RecentAuthentication recent;private final AccessPolicy access;private final GrowthLibrary roles;
 public ClinicIntegration(JdbcTemplate db,ClinicalCare care,ClinicCommerce commerce,ProfessionalAuthority authority,RecentAuthentication recent,AccessPolicy access,GrowthLibrary roles){this.db=db;this.care=care;this.commerce=commerce;this.authority=authority;this.recent=recent;this.access=access;this.roles=roles;}
 private Object safe(Object r){return ProfessionalAuthority.jsonSafe(r);}
 private void actor(UUID who,UUID sid){care.actor(who,sid);}
 private void operator(UUID who,UUID sid,String role){actor(who,sid);recent.require(who,sid,true);if(!has(who,role))throw new ForbiddenException("Current explicit purpose authority required: "+role);}
 private boolean has(UUID who,String role){return Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=? AND r.name=?)",Boolean.class,who,role));}
 private Map<String,Object> own(UUID who,UUID sid,UUID id){actor(who,sid);var r=db.queryForList("SELECT c.*,e.id AS encounter_id,e.completed_at FROM consultation_requests c LEFT JOIN clinic_care_relationships r ON r.appointment_id=c.id LEFT JOIN clinic_encounters e ON e.relationship_id=r.id WHERE c.id=? AND c.clinic_governed AND(c.requester_user_id=? OR c.professional_user_id=?)",id,who,who);if(r.isEmpty())throw new NotFoundException("Own clinic appointment required");return r.getFirst();}
 public record Recommendation(UUID appointmentId,UUID followupId,long revision,String body,Instant suggestedAfter,Instant expiresAt){}
 public UUID recommend(UUID who,UUID sid,Recommendation in){care.followupProcessing();var a=own(who,sid,in.appointmentId());if(!who.equals(a.get("professional_user_id")))throw new ForbiddenException("Only the assigned professional authors recommendations");recent.require(who,sid,true);authority.lock(who);access.requireCare((UUID)a.get("requester_user_id"),who,(String)a.get("consultation_mode"));if(!"COMPLETED".equals(a.get("status"))||a.get("completed_at")==null)throw new ConflictException("Evidenced completed encounter required");UUID boundPolicy=care.followupPolicy();care.followupAccess(who,sid,(UUID)a.get("encounter_id"),boundPolicy);ProfessionalAuthority.text(in.body(),5000);if(in.suggestedAfter()==null||in.expiresAt()==null||in.suggestedAfter().isBefore(Instant.now())||!in.expiresAt().isAfter(in.suggestedAfter())||in.expiresAt().isAfter(Instant.now().plus(Duration.ofDays(366))))throw new IllegalArgumentException("Explicit future bounded recommendation required");
  UUID id=in.followupId();long revision=1;if(id==null){if(in.revision()!=0)throw new ConflictException("New recommendation starts at revision zero");id=db.queryForObject("INSERT INTO clinic_followups(appointment_id,professional_id,patient_id) VALUES(?,?,?) RETURNING id",UUID.class,in.appointmentId(),who,a.get("requester_user_id"));}else{var old=db.queryForList("SELECT id FROM clinic_followups WHERE id=? AND appointment_id=? AND professional_id=?",id,in.appointmentId(),who);if(old.isEmpty())throw new NotFoundException("Own recommendation required");var previousPolicy=db.queryForMap("SELECT policy_id FROM clinic_followup_versions WHERE followup_id=? ORDER BY revision DESC LIMIT 1",id);care.followupAccess(who,sid,(UUID)a.get("encounter_id"),(UUID)previousPolicy.get("policy_id"));revision=db.queryForObject("SELECT COALESCE(max(revision),0)+1 FROM clinic_followup_versions WHERE followup_id=?",Long.class,id);if(in.revision()!=revision-1)throw new ConflictException("Reload the recommendation before revising");}
  db.update("INSERT INTO clinic_followup_versions(followup_id,revision,author_id,body_cipher,suggested_after,expires_at,policy_id) VALUES(?,?,?,?,?,?,?)",id,revision,who,care.seal(in.body(),"followup:"+id+":"+revision),time(in.suggestedAfter()),time(in.expiresAt()),boundPolicy);return id;}
 public Object followups(UUID who,UUID sid){actor(who,sid);care.followupProcessing();var rows=db.queryForList("SELECT f.id,f.appointment_id,f.patient_id,f.professional_id,v.policy_id,v.revision,v.body_cipher,v.suggested_after,v.expires_at,c.choice,c.remind_at FROM clinic_followups f JOIN LATERAL(SELECT * FROM clinic_followup_versions WHERE followup_id=f.id ORDER BY revision DESC LIMIT 1)v ON TRUE LEFT JOIN LATERAL(SELECT choice,remind_at FROM clinic_followup_choices WHERE followup_id=f.id AND revision=v.revision ORDER BY ordinal DESC LIMIT 1)c ON TRUE WHERE f.patient_id=? OR f.professional_id=? ORDER BY f.created_at DESC LIMIT 100",who,who);for(var r:rows){var a=own(who,sid,(UUID)r.get("appointment_id"));care.followupAccess(who,sid,(UUID)a.get("encounter_id"),(UUID)r.remove("policy_id"));r.put("body",care.open((byte[])r.remove("body_cipher"),"followup:"+r.get("id")+":"+r.get("revision")));}return safe(rows);}
 public void choose(UUID who,UUID sid,UUID id,long revision,String choice,Instant remind){actor(who,sid);care.followupProcessing();var rows=db.queryForList("SELECT f.*,v.expires_at FROM clinic_followups f JOIN clinic_followup_versions v ON v.followup_id=f.id WHERE f.id=? AND f.patient_id=? AND v.revision=?",id,who,revision);if(rows.isEmpty())throw new NotFoundException("Own recommendation version required");var r=rows.getFirst();authority.lock((UUID)r.get("professional_id"));long latest=db.queryForObject("SELECT max(revision) FROM clinic_followup_versions WHERE followup_id=?",Long.class,id);if(latest!=revision)throw new ConflictException("Read the latest recommendation before choosing");if(!Set.of("ACCEPT","DECLINE","WITHDRAW").contains(choice))throw new IllegalArgumentException("Choose explicitly");if(choice.equals("ACCEPT")){var a=own(who,sid,(UUID)r.get("appointment_id"));access.requireCare(who,(UUID)r.get("professional_id"),(String)a.get("consultation_mode"));if(!((java.sql.Timestamp)r.get("expires_at")).toInstant().isAfter(Instant.now())||!care.consentLive((UUID)a.get("id"),(String)a.get("consultation_mode")))throw new ConflictException("Current consent and unexpired recommendation required");}if(remind!=null&&(!choice.equals("ACCEPT")||!remind.isAfter(Instant.now())||!remind.isBefore(((java.sql.Timestamp)r.get("expires_at")).toInstant())))throw new IllegalArgumentException("Reminder is an optional future patient choice within recommendation validity");db.update("INSERT INTO clinic_followup_choices(followup_id,revision,patient_id,choice,remind_at) VALUES(?,?,?,?,?)",id,revision,who,choice,time(remind));}
 public Map<String,Object> reschedule(UUID who,UUID sid,UUID old,long revision,ClinicCommerce.Booking booking){var a=own(who,sid,old);if(!who.equals(a.get("requester_user_id")))throw new ForbiddenException("Only the patient explicitly accepts a replacement booking");db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","clinic-patient:"+who);var existing=db.queryForList("SELECT * FROM clinic_booking_changes WHERE old_appointment_id=?",old);if(!existing.isEmpty()){var r=existing.getFirst();if(!booking.retryKey().equals(r.get("retry_key")))throw new ConflictException("Appointment already has a replacement");return commerce.book(who,booking);}
  var owners=db.queryForList("SELECT professional_user_id FROM professional_availability_slots WHERE id=?",booking.slotId());if(owners.isEmpty())throw new NotFoundException("Replacement slot required");var locks=new TreeSet<UUID>();locks.add((UUID)a.get("professional_user_id"));locks.add((UUID)owners.getFirst().get("professional_user_id"));for(UUID pro:locks)authority.lock(pro);
  if(Set.of("REQUESTED","PAYMENT_PENDING","CONFIRMED").contains(a.get("status")))commerce.change(who,old,new ClinicCommerce.Change(revision,"CANCEL","Explicit replacement booking; original payment and refund review remain separate"));else if(!Set.of("CANCELLED_BY_PATIENT","CANCELLED_BY_PROFESSIONAL","CANCELLED_BY_PLATFORM","PROFESSIONAL_NO_SHOW","PATIENT_NO_SHOW","TECHNICAL_FAILURE","COMPLETED").contains(a.get("status")))throw new ConflictException("Finish the active encounter before booking a replacement");var booked=commerce.book(who,booking);db.update("INSERT INTO clinic_booking_changes(old_appointment_id,new_appointment_id,patient_id,retry_key) VALUES(?,?,?,?)",old,booked.get("id"),who,booking.retryKey());return booked;}
 public UUID incident(UUID who,UUID sid,UUID appointment,String kind){own(who,sid,appointment);if(!Set.of("CONNECTION","PAYMENT","ATTENDANCE","PRIVACY","OTHER").contains(kind))throw new IllegalArgumentException("Choose an incident category");db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","clinic-incidents:"+who);if(db.queryForObject("SELECT count(*) FROM clinic_operational_incidents WHERE reporter_id=? AND created_at>CURRENT_TIMESTAMP-INTERVAL '1 day'",Long.class,who)>=30)throw new ConflictException("Wait before submitting more incident reports");return db.queryForObject("INSERT INTO clinic_operational_incidents(appointment_id,reporter_id,kind) VALUES(?,?,?) RETURNING id",UUID.class,appointment,who,kind);}
 private void reference(String value){ProfessionalAuthority.text(value,1000);if(value.length()<10||value.contains("@")||value.contains("\n"))throw new IllegalArgumentException("Use a bounded case/evidence reference, not a narrative or contact details");}
 public UUID incidentReview(UUID who,UUID sid,UUID incident,String classification,String evidence){operator(who,sid,"CLINIC_OPERATIONS");reference(evidence);if(!Set.of("NO_OUTAGE","TECHNICAL_FAILURE","UNRESOLVED").contains(classification))throw new IllegalArgumentException("Choose a reviewed classification");var rows=db.queryForList("SELECT i.*,c.requester_user_id,c.professional_user_id FROM clinic_operational_incidents i JOIN consultation_requests c ON c.id=i.appointment_id WHERE i.id=?",incident);if(rows.isEmpty())throw new NotFoundException("Incident required");var r=rows.getFirst();if(who.equals(r.get("reporter_id"))||who.equals(r.get("requester_user_id"))||who.equals(r.get("professional_user_id")))throw new ForbiddenException("An independent operations reviewer is required");return db.queryForObject("INSERT INTO clinic_incident_reviews(incident_id,author_id,evidence_reference,classification) VALUES(?,?,?,?) RETURNING id",UUID.class,incident,who,evidence,classification);}
 public void approveIncident(UUID who,UUID sid,UUID review){operator(who,sid,"CLINIC_OPERATIONS");var rows=db.queryForList("SELECT r.author_id,i.reporter_id,c.requester_user_id,c.professional_user_id FROM clinic_incident_reviews r JOIN clinic_operational_incidents i ON i.id=r.incident_id JOIN consultation_requests c ON c.id=i.appointment_id WHERE r.id=?",review);if(rows.isEmpty())throw new NotFoundException("Review required");if(rows.getFirst().values().contains(who))throw new ForbiddenException("A second independent operations reviewer is required");db.update("INSERT INTO clinic_incident_decisions(review_id,reviewer_id) VALUES(?,?) ON CONFLICT(review_id) DO NOTHING",review,who);}
 public UUID rights(UUID who,UUID sid,UUID appointment,String category,String kind,UUID retry){actor(who,sid);db.queryForList("SELECT pg_advisory_xact_lock(hashtextextended(?,0))","clinic-rights:"+who);if(appointment!=null)own(who,sid,appointment);if(!Set.of("ACCESS","EXPORT","CORRECTION","ERASURE","RESTRICTION","APPEAL").contains(kind)||retry==null||db.queryForList("SELECT category FROM clinic_data_classes WHERE category=?",category).isEmpty())throw new IllegalArgumentException("Choose a defined data class and rights request");var old=db.queryForList("SELECT * FROM clinic_rights_requests WHERE requester_id=? AND retry_key=?",who,retry);if(!old.isEmpty()){var r=old.getFirst();if(!Objects.equals(appointment,r.get("appointment_id"))||!category.equals(r.get("category"))||!kind.equals(r.get("request_kind")))throw new ConflictException("Rights retry key is bound to another request");return(UUID)r.get("id");}if(db.queryForObject("SELECT count(*) FROM clinic_rights_requests WHERE requester_id=? AND created_at>CURRENT_TIMESTAMP-INTERVAL '1 day'",Long.class,who)>=20)throw new ConflictException("Wait before submitting more rights requests");UUID id=db.queryForObject("INSERT INTO clinic_rights_requests(requester_id,appointment_id,category,request_kind,retry_key) VALUES(?,?,?,?,?) RETURNING id",UUID.class,who,appointment,category,kind,retry);db.update("INSERT INTO clinic_rights_events(request_id,actor_id,state,evidence_reference) VALUES(?,?,'RECEIVED','SUBJECT_REQUEST_NO_AUTOMATIC_DELETION')",id,who);return id;}
 public Object ownRights(UUID who,UUID sid){actor(who,sid);return safe(db.queryForList("SELECT r.*,e.state,e.evidence_reference,e.created_at AS event_at FROM clinic_rights_requests r JOIN clinic_rights_events e ON e.request_id=r.id WHERE r.requester_id=? ORDER BY e.created_at DESC,e.id DESC LIMIT 200",who));}
 public void reviewRights(UUID who,UUID sid,UUID request,String state,String evidence){operator(who,sid,"CLINIC_PRIVACY_OPERATOR");reference(evidence);if(!Set.of("UNDER_REVIEW","AUTHORIZED_PROCESSOR_REQUIRED","ACTION_EVIDENCED","EXCEPTION_REVIEW").contains(state))throw new IllegalArgumentException("Choose a reviewed request state");var rows=db.queryForList("SELECT * FROM clinic_rights_requests WHERE id=? FOR UPDATE",request);if(rows.isEmpty())throw new NotFoundException("Rights request required");var r=rows.getFirst();if(who.equals(r.get("requester_id")))throw new ForbiddenException("Independent privacy review required");if(state.equals("ACTION_EVIDENCED")){if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_legal_holds h JOIN clinic_hold_reviews v ON v.hold_id=h.id WHERE h.user_id=? AND h.category=? AND h.expires_at>CURRENT_TIMESTAMP)",Boolean.class,r.get("requester_id"),r.get("category"))))throw new ConflictException("Resolve the current category hold before evidencing the requested action");if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM clinic_rights_events WHERE request_id=? AND actor_id<>? AND state='UNDER_REVIEW')",Boolean.class,request,who)))throw new ForbiddenException("A separate privacy operator must review before action evidence is recorded");}db.update("INSERT INTO clinic_rights_events(request_id,actor_id,state,evidence_reference) VALUES(?,?,?,?)",request,who,state,evidence);}
 public UUID hold(UUID who,UUID sid,UUID subject,String category,String evidence,Instant until){operator(who,sid,"CLINIC_PRIVACY_OPERATOR");reference(evidence);if(who.equals(subject)||until==null||!until.isAfter(Instant.now())||until.isAfter(Instant.now().plus(Duration.ofDays(366))))throw new IllegalArgumentException("Bounded independently reviewed hold required");return db.queryForObject("INSERT INTO clinic_legal_holds(user_id,category,author_id,evidence_reference,expires_at) VALUES(?,?,?,?,?) RETURNING id",UUID.class,subject,category,who,evidence,time(until));}
 public void approveHold(UUID who,UUID sid,UUID id){operator(who,sid,"CLINIC_PRIVACY_OPERATOR");var rows=db.queryForList("SELECT * FROM clinic_legal_holds WHERE id=? AND expires_at>CURRENT_TIMESTAMP",id);if(rows.isEmpty())throw new NotFoundException("Current hold required");if(who.equals(rows.getFirst().get("author_id"))||who.equals(rows.getFirst().get("user_id")))throw new ForbiddenException("Independent hold approval required");db.update("INSERT INTO clinic_hold_reviews(hold_id,reviewer_id) VALUES(?,?) ON CONFLICT DO NOTHING",id,who);}
 public Object manifest(UUID who,UUID sid){actor(who,sid);return safe(db.queryForList("SELECT * FROM clinic_data_classes ORDER BY category"));}
 public Object operations(UUID who,UUID sid,String view){actor(who,sid);return switch(view){
  case "PROFESSIONAL" -> {authority.owner(who);recent.require(who,sid,true);yield Map.of("appointments",commerce.appointments(who),"credentials",safe(db.queryForList("SELECT qualification_state,valid_until,recheck_at FROM professional_verifications WHERE professional_user_id=?",who)),"availability",safe(db.queryForList("SELECT id,status,starts_at,ends_at FROM professional_availability_slots WHERE professional_user_id=? AND ends_at>CURRENT_TIMESTAMP ORDER BY starts_at LIMIT 100",who)));}
  case "FINANCE" -> {recent.require(who,sid,true);yield Map.of("summary",commerce.operations(who),"refunds",safe(db.queryForList("SELECT appointment_id,state,initiate_by,updated_at FROM clinic_refunds ORDER BY initiate_by LIMIT 100")),"paymentFailures",safe(db.queryForList("SELECT id,state,updated_at FROM clinic_payment_intents WHERE state IN('FAILED','TIMED_OUT','RECONCILIATION_REQUIRED') LIMIT 100")),"settlementReview",safe(db.queryForList("SELECT s.appointment_id,s.state,s.amount_units,EXISTS(SELECT 1 FROM clinic_refunds r WHERE r.appointment_id=s.appointment_id) AS refund_hold FROM clinic_settlement_requests s WHERE s.state='PROCESSING' OR EXISTS(SELECT 1 FROM clinic_refunds r WHERE r.appointment_id=s.appointment_id) LIMIT 100")));}
  case "SAFETY" -> {operator(who,sid,"CLINIC_OPERATIONS");yield Map.of("incidents",safe(db.queryForList("SELECT i.*,r.id AS review_id,r.classification,d.id AS decision_id FROM clinic_operational_incidents i LEFT JOIN clinic_incident_reviews r ON r.incident_id=i.id LEFT JOIN clinic_incident_decisions d ON d.review_id=r.id ORDER BY i.created_at DESC LIMIT 100")),"credentials",safe(db.queryForList("SELECT professional_user_id,qualification_state,valid_until,recheck_at FROM professional_verifications WHERE qualification_state IN('REVOKED','SUSPENDED') OR valid_until<CURRENT_TIMESTAMP OR recheck_at<CURRENT_TIMESTAMP LIMIT 100")),"concerns",safe(db.queryForList("SELECT id,kind,state,professional_id FROM clinic_reputation_cases WHERE state='OPEN' LIMIT 100")));}
  case "PRIVACY" -> {operator(who,sid,"CLINIC_PRIVACY_OPERATOR");yield Map.of("requests",safe(db.queryForList("SELECT r.*,e.state,e.evidence_reference FROM clinic_rights_requests r JOIN LATERAL(SELECT state,evidence_reference FROM clinic_rights_events WHERE request_id=r.id ORDER BY created_at DESC,id DESC LIMIT 1)e ON TRUE ORDER BY r.created_at LIMIT 100")),"holds",safe(db.queryForList("SELECT h.*,v.reviewer_id FROM clinic_legal_holds h LEFT JOIN clinic_hold_reviews v ON v.hold_id=h.id WHERE expires_at>CURRENT_TIMESTAMP LIMIT 100")),"automaticPurgeEnabled",false,"retentionReview",Map.of("mode","REPORT_ONLY_NO_APPROVED_DELETION_CANDIDATES","approvedDeletionCandidates",0,"classesAwaitingPolicy",db.queryForObject("SELECT count(*) FROM clinic_data_classes WHERE retention LIKE 'UNAPPROVED%'",Long.class),"requestsAwaitingReview",db.queryForObject("SELECT count(*) FROM clinic_rights_requests",Long.class)),"dryRunOnly",true);}
  case "BUSINESS" -> {recent.require(who,sid,true);roles.admin(who);yield Map.of("aggregate",safe(db.queryForMap("SELECT count(*) AS bookings,count(*) FILTER(WHERE price_units=0) AS free_bookings,count(*) FILTER(WHERE status='COMPLETED' AND price_units>0) AS completed_paid_services,count(DISTINCT professional_user_id) AS participating_professionals FROM consultation_requests WHERE clinic_governed")),"ledgerTotals",safe(db.queryForList("SELECT kind,sum(amount_units) AS amount_units FROM clinic_financial_events GROUP BY kind")),"subscriptionReceipts",safe(db.queryForMap("SELECT COALESCE(sum(e.amount_units),0) AS amount_units FROM clinic_subscription_orders o JOIN clinic_provider_events e ON e.id=(SELECT provider_event_id FROM clinic_professional_subscriptions WHERE order_id=o.id) WHERE o.state='ACTIVE'")));}
  default -> throw new IllegalArgumentException("Choose a purpose-specific view");};}
 public void preferences(UUID who,UUID sid,boolean enabled,String zone,int start,int end){actor(who,sid);ZoneId.of(zone);if(start<0||start>23||end<0||end>23)throw new IllegalArgumentException("Choose valid quiet hours");db.update("INSERT INTO clinic_notification_preferences(user_id,optional_enabled,zone_id,quiet_start,quiet_end) VALUES(?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET optional_enabled=EXCLUDED.optional_enabled,zone_id=EXCLUDED.zone_id,quiet_start=EXCLUDED.quiet_start,quiet_end=EXCLUDED.quiet_end",who,enabled,zone,start,end);}
 public Object preferences(UUID who,UUID sid){actor(who,sid);var r=db.queryForList("SELECT optional_enabled,zone_id,quiet_start,quiet_end FROM clinic_notification_preferences WHERE user_id=?",who);return r.isEmpty()?Map.of("optional_enabled",false,"zone_id","UTC","quiet_start",22,"quiet_end",8):r.getFirst();}
 public int reminders(UUID who,UUID sid){operator(who,sid,"CLINIC_OPERATIONS");care.followupProcessing();int count=0;for(var r:db.queryForList("SELECT f.id,f.patient_id,v.revision FROM clinic_followups f JOIN LATERAL(SELECT * FROM clinic_followup_versions WHERE followup_id=f.id ORDER BY revision DESC LIMIT 1)v ON TRUE JOIN LATERAL(SELECT * FROM clinic_followup_choices WHERE followup_id=f.id AND revision=v.revision ORDER BY ordinal DESC LIMIT 1)c ON TRUE JOIN clinic_notification_preferences p ON p.user_id=f.patient_id WHERE v.policy_id IS NOT NULL AND c.choice='ACCEPT' AND c.remind_at<=CURRENT_TIMESTAMP AND v.expires_at>CURRENT_TIMESTAMP AND p.optional_enabled LIMIT 100")){UUID patient=(UUID)r.get("patient_id");var source=db.queryForMap("SELECT c.* FROM clinic_followups f JOIN consultation_requests c ON c.id=f.appointment_id WHERE f.id=?",r.get("id"));try{access.requireCare(patient,(UUID)source.get("professional_user_id"),(String)source.get("consultation_mode"));if(!care.consentLive((UUID)source.get("id"),(String)source.get("consultation_mode")))continue;}catch(ForbiddenException unavailable){continue;}var p=db.queryForMap("SELECT * FROM clinic_notification_preferences WHERE user_id=?",patient);int hour=Instant.now().atZone(ZoneId.of((String)p.get("zone_id"))).getHour(),start=((Number)p.get("quiet_start")).intValue(),end=((Number)p.get("quiet_end")).intValue();boolean quiet=start==end||start<end&&hour>=start&&hour<end||start>end&&(hour>=start||hour<end);if(quiet)continue;String key="followup:"+r.get("id")+":"+r.get("revision");if(db.update("INSERT INTO clinic_notice_deliveries(user_id,dedup_key) VALUES(?,?) ON CONFLICT DO NOTHING",patient,key)==1){db.update("INSERT INTO notifications(user_id,type,title,body) VALUES(?,'SYSTEM_NOTICE','Account update','An update you requested is available in your authenticated account. Open the app to review your choices.')",patient);count++;}}return count;}
}
